var getLabelFormate = require( './props/label-formate/get.js' );
var setPlotAreaHeight = require( './props/plot-area-height/set.js' );
var getPlotAreaHeight = require( './props/plot-area-height/get.js' );
var setPlotAreaWidth = require( './props/plot-area-width/set.js' );
var getPlotAreaWidth = require( './props/plot-area-width/get.js' );
var setTicsStride = require( './props/tics-spacing/set.js' );
var getTicsStride = require( './props/tics-spacing/get.js' );
var setVerticalTicsGlyph = require( './props/vertical-tics-glyph/set.js' );
var getDrawFrame = require( './props/draw-frame/get.js' );
var setDrawFrame = require( './props/draw-frame/set.js' );
var getVerticalTicsGlyph = require( './props/vertical-tics-glyph/get.js' );
var getWidth = require( './props/width/get.js' );
